UPDATE posts SET title = 'Panduan Lengkap Pola Asuh Demokratis Anak Masa Kini', excerpt = 'Pelajari pola asuh demokratis yang memprioritaskan komunikasi dua arah dan empati untuk membangun karakter anak mandiri.', category = 'Pola Asuh', tags = 'pola-asuh, parenting, psikologi-anak, kemandirian' WHERE id = 1;
UPDATE posts SET title = '5 Aktivitas Sensory Play Seru untuk Melatih Motorik Balita', excerpt = 'Stimulasi indra anak sejak dini melalui ragam permainan sensori sederhana di rumah yang terbukti mengasah motorik halus dan kasar.', category = 'Tumbuh Kembang', tags = 'sensory-play, tumbuh-kembang, balita, motorik' WHERE id = 2;
UPDATE posts SET title = 'Mengenal Nutrisi Esensial & Bahaya Stunting Sejak 1000 HPK', excerpt = 'Pentingnya asupan protein hewani, zat besi, dan mikronutrien penting untuk mencegah gagal tumbuh kembang pada balita.', category = 'Kesehatan & Gizi', tags = 'stunting, gizi-anak, 1000-hpk, nutrisi' WHERE id = 3;